lemma.raw:
\label{lowdegree}
The map $h:H^i_K(X,{{\mathbb Z}}(n))\to H^i_{\mathcal M}(X,{{\mathbb Q}}(n))$ 
is bijective for $i<n$ and injective for $i=n$.

proposition.raw:
\label{prop1}
We have an exact sequence 
\begin{equation}\label{homd}
\cdots\to H_i^c(X,A(n)) \to H_{i+1}^F(X,A(n))\to H_{i+1}^K(X,A(n)) \to 
H_{i-1}^c(X,A(n)) \to \cdots 
\end{equation}
All three theories are covariently functorial for proper maps,
contravariantly functorial for quasi-finite flat maps,
and have localization long exact sequences.

\label{ssprop}
We have functorial spectral sequences
\begin{align*}
E^1_{s,t}=\bigoplus_{X_{(s)}}
H^{s-t}_{\mathcal M}(k(x),A(s-n))&\Rightarrow H_{s+t}^c(X,A(n));\\
\bar E^1_{s,t}=\bigoplus_{X_{(s)}}
H^{s-t}_F(k(x),A(s-n))&\Rightarrow H_{s+t+1}^F(X,A(n)).\\
\end{align*}

For $p\not| m$ we have a spectral sequence
\begin{equation}\label{polk}
\tilde E^1_{s,t}=\bigoplus_{X_{(s)}}
H^{s-t}_{\text{\rm et}}(k(x),\mu_m^{\otimes s-n})
\Rightarrow H_{s+t}^{\text{\rm et}}(X,{{\mathbb Z}}/m(n))
\end{equation}
The $\tilde E^1$-terms lie in short exact sequences
\begin{multline}\label{galoismodm}
0\to H^{s-t-1}_{\text{\rm et}}(k(x)\otimes_{{{\mathbb F}}_q}\bar {{\mathbb F}}_q,\mu_m^{\otimes s-n})_G
\to H^{s-t}_{\text{\rm et}}(k(x),\mu_m^{\otimes s-n})\to \\ 
H^{s-t}_{\text{\rm et}}(k(x)\otimes_{{{\mathbb F}}_q}\bar {{\mathbb F}}_q,\mu_m^{\otimes s-n})^G\to  0. 
\end{multline}

We have a commutative diagram with exact rows
\begin{equation}\label{maind}\begin{CD}
@>>>{\bf H^i_{\mathcal M}(X,{{\mathbb Z}}(n))} @>\alpha >>{\bf  H^i_F(X,{{\mathbb Z}}(n))} 
@>\beta>> {\bf H^{i-1}_K(X,{{\mathbb Z}}(n))} @>\gamma>>\\
@EEE @Vf VV  @Vg VV @VhVV  \\
@>>> H^i_{\text{\rm et}}(X,{{\mathbb Z}}(n)) @>>> {\bf H^i_W(X,{{\mathbb Z}}(n)) }@>>> H^{i-1}_{\mathcal M}(X,{{\mathbb Q}}(n))@>>>
\end{CD}\end{equation}

We have an exact sequence
\begin{multline*}
0\to \ker u\to \ker c\to {\rm div}\; H^i_{\text{\rm et}}(X,{{\mathbb Z}}(n))\otimes{{\mathbb Z}}_l \\
\to \operatorname{coker} u\to \operatorname{coker} c\to T_lH^{i+1}(X_{\text{\rm et}},{{\mathbb Z}}(n))\to 0.
\end{multline*}
The groups $\ker u$ and $\operatorname{coker} u$ are torsion.

corollary.raw:
\label{tatecor}
Under Conjecture \ref{lichtconj}, the kernel and cokernel of $u$ are 
equal to the kernel and cokernel of the cycle map, respectively.

conjecture.raw:
\label{mainhom}
The groups $H_i^c(X,{{\mathbb Z}}(n))$, $H_{i}^F(X,{{\mathbb Z}}(n))$ and $H_{i}^K(X,{{\mathbb Z}}(n))$
are finitely generated for any $i, n$ and $X$.

\label{lichtconj}
The group $H^i_{\text{\rm et}}(X,{{\mathbb Z}}(n))$ is finite for all $i\not=2n,2n+1$,
finitely generated for all $i=2n$, and of cofinite type for $i=2n+2$.

